package com.aoo.bcg.common.error;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DomainFailureTest{@Test void preservesCodeCauseTraceAndAllowsOnlyOneStackLog(){var cause=new java.sql.SQLException("private detail");var failure=new DomainFailure(3001,"房间不存在","trace-1",cause);assertEquals(3001,failure.publicError().code());assertEquals("trace-1",failure.publicError().traceId());assertSame(cause,failure.getCause());assertTrue(failure.claimStackLog());assertFalse(failure.claimStackLog());assertFalse(failure.publicError().message().contains("private"));}}
